    // Mobile Menu Toggle
    const mobileMenuBtn = document.querySelector('.mobile-menu-btn');
    const mainNav = document.getElementById('main-nav');

    if (mobileMenuBtn && mainNav) {
        mobileMenuBtn.addEventListener('click', () => {
            const isExpanded = mobileMenuBtn.getAttribute('aria-expanded') === 'true';
            mobileMenuBtn.setAttribute('aria-expanded', !isExpanded);
            mainNav.classList.toggle('is-open');
        });

        // Close menu on escape
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && mainNav.classList.contains('is-open')) {
                mobileMenuBtn.setAttribute('aria-expanded', 'false');
                mainNav.classList.remove('is-open');
                mobileMenuBtn.focus();
            }
        });
    }

    // Cart Interaction
    const addToCartBtns = document.querySelectorAll('.add-to-cart');
    const cartBadge = document.getElementById('cart-badge');
    const cartBtn = document.getElementById('cart-btn');
    const srAnnouncer = document.getElementById('sr-announcer');
    let cartCount = 0;

    addToCartBtns.forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.preventDefault(); // Prevent stretched link activation
            cartCount++;
            cartBadge.textContent = cartCount;

            // Update cart aria-label
            const itemWord = cartCount === 1 ? 'item' : 'items';
            cartBtn.setAttribute('aria-label', `Shopping Cart, ${cartCount} ${itemWord}`);

            // Announce to screen readers
            const productName = btn.getAttribute('data-name') || 'Item';
            announceMessage(`${productName} added to cart. You now have ${cartCount} ${itemWord} in your cart.`);

            // Simple visual feedback
            const originalText = btn.innerHTML;
            btn.innerHTML = 'Added!<span class="sr-only">, ' + productName + '</span>';
            setTimeout(() => {
                btn.innerHTML = originalText;
            }, 2000);
        });
    });

    // Newsletter Form Validation
    const newsletterForm = document.getElementById('newsletter-form');
    const newsletterError = document.getElementById('newsletter-error');

    if (newsletterForm) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const emailInput = document.getElementById('newsletter-email');

            if (!emailInput.value || !emailInput.value.includes('@')) {
                newsletterError.textContent = 'Please enter a valid email address.';
                emailInput.setAttribute('aria-invalid', 'true');
                emailInput.focus();
            } else {
                newsletterError.textContent = '';
                emailInput.removeAttribute('aria-invalid');
                announceMessage('Successfully subscribed to newsletter.');

                // Reset form
                newsletterForm.reset();

                // Show success state
                const btn = newsletterForm.querySelector('button');
                const originalBtnText = btn.textContent;
                btn.textContent = 'Subscribed!';
                setTimeout(() => {
                    btn.textContent = originalBtnText;
                }, 3000);
            }
        });

        // Clear error on input
        const emailInput = document.getElementById('newsletter-email');
        if (emailInput) {
            emailInput.addEventListener('input', () => {
                if (emailInput.hasAttribute('aria-invalid')) {
                    emailInput.removeAttribute('aria-invalid');
                    newsletterError.textContent = '';
                }
            });
        }
    }

    // Helper to announce messages to screen readers
    function announceMessage(message) {
        if (srAnnouncer) {
            srAnnouncer.textContent = message;
            // Clear after read
            setTimeout(() => {
                srAnnouncer.textContent = '';
            }, 3000);
        }
    }
